import {
    Table,
    BooleanColumn,
    GenericColumn,
    ReferenceColumn,
    FieldNameColumn,
    ConditionsColumn,
    TranslatedTextColumn,
    StringColumn,
    IntegerColumn,
    GuidColumn,
    TableNameColumn,
} from '../../db'

export const sp_rectangle_menu_item = Table({
    allowWebServiceAccess: true,
    audit: true,
    display: 'label',
    extends: 'sys_metadata',
    label: 'Menu Item',
    name: 'sp_rectangle_menu_item',
    schema: {
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        color: GenericColumn({
            columnType: 'bootstrap_color',
            default: 'default',
            choices: {
                success: {
                    label: 'Success',
                    sequence: 3,
                },
                info: {
                    label: 'Info',
                    sequence: 4,
                },
                warning: {
                    label: 'Warning',
                    sequence: 5,
                },
                default: {
                    label: 'Default',
                    sequence: 1,
                },
                danger: {
                    label: 'Danger',
                    sequence: 6,
                },
                primary: {
                    label: 'Primary',
                    sequence: 2,
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Bootstrap color',
        }),
        sc_category: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Catalog category',
            referenceTable: 'sc_category',
        }),
        sc_cat_item: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Catalog item',
            referenceTable: 'sc_cat_item',
        }),
        condition: GenericColumn({
            columnType: 'condition_string',
            label: [
                {
                    hint: 'Evalauted on the server',
                    label: 'Condition',
                    plural: 'Conditions',
                    language: 'en',
                },
            ],
            maxLength: 254,
        }),
        display_1: FieldNameColumn({
            attributes: {
                allow_null: true,
                allow_references: true,
            },
            dependent: 'table',
            label: 'Display 1',
        }),
        display_2: FieldNameColumn({
            attributes: {
                allow_null: true,
                allow_references: true,
            },
            dependent: 'table',
            label: 'Display 2',
        }),
        display_date: FieldNameColumn({
            attributes: {
                types: 'glide_date;glide_date_time',
            },
            dependent: 'table',
            label: 'Display date',
        }),
        filter: ConditionsColumn({
            attributes: {
                allow_order: true,
            },
            dependent: 'table',
            label: 'Filter',
            maxLength: 4000,
        }),
        glyph: GenericColumn({
            attributes: {
                iconset: 'fontawesome',
            },
            columnType: 'glyphicon',
            label: 'Glyph',
        }),
        hint: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Hint',
            maxLength: 255,
        }),
        url: StringColumn({
            label: 'HREF / URL',
            maxLength: 255,
        }),
        kb_article: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'KB article',
            referenceTable: 'kb_knowledge',
        }),
        kb_category: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'KB category',
            referenceTable: 'kb_category',
        }),
        kb_topic: StringColumn({
            dropdown: 'dropdown_with_none',
            dynamicValueDefinitions: {
                type: 'choices_from_other_table',
                table: 'kb_knowledge',
                field: 'topic',
            },
            label: 'KB topic',
        }),
        label: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Label',
            maxLength: 255,
        }),
        order: IntegerColumn({
            default: '100',
            label: 'Order',
        }),
        sp_page: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Page',
            referenceTable: 'sp_page',
        }),
        sp_rectangle_menu: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Parent Menu',
            referenceTable: 'sp_instance_menu',
        }),
        sp_rectangle_menu_item: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Parent Menu Item',
            referenceTable: 'sp_rectangle_menu_item',
        }),
        record_script: GenericColumn({
            columnType: 'script_server',
            label: 'Server Script',
            maxLength: 65000,
        }),
        short_description: StringColumn({
            label: 'Short description',
            maxLength: 100,
        }),
        sys_id: GuidColumn({
            label: 'Sys ID',
            primary: true,
        }),
        table: TableNameColumn({
            attributes: {
                allow_public: true,
                base_start: true,
            },
            label: 'Table',
        }),
        type: StringColumn({
            default: 'page',
            choices: {
                kb_topic: {
                    label: 'KB Topic',
                    sequence: 6,
                },
                scripted: {
                    label: 'Scripted List',
                    sequence: 10,
                },
                sc: {
                    label: 'Service Catalog',
                    sequence: 2,
                },
                kb_article: {
                    label: 'KB Article',
                    sequence: 7,
                },
                sc_category: {
                    label: 'Catalog Category',
                    sequence: 3,
                },
                kb_category: {
                    label: 'KB Category',
                    sequence: 8,
                },
                page: {
                    label: 'Page',
                    sequence: 0,
                },
                sc_cat_item: {
                    label: 'Catalog Item',
                    sequence: 4,
                },
                filtered: {
                    label: 'Filtered List',
                    sequence: 9,
                },
                url: {
                    label: 'URL',
                    sequence: 1,
                },
                kb: {
                    label: 'Knowledge Base',
                    sequence: 5,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Type',
        }),
        url_target: StringColumn({
            label: 'URL target',
        }),
    },
})
